-- Materialized views, TO tables, aggregating pipelines, dictionaries, views
CREATE MATERIALIZED VIEW mv_daily TO daily_agg AS SELECT toDate(ts) AS day, key, uniqState(user_id) AS uniq_state FROM events GROUP BY day, key;
CREATE MATERIALIZED VIEW IF NOT EXISTS mv_hourly TO hourly_sum AS SELECT toStartOfHour(ts) AS hour, sum(value) AS total FROM metrics GROUP BY hour;
CREATE MATERIALIZED VIEW mv_engine ENGINE = SummingMergeTree ORDER BY (day, key) POPULATE AS SELECT toDate(ts) AS day, key, count() AS c FROM events GROUP BY day, key;
CREATE MATERIALIZED VIEW mv_engine2 ENGINE = AggregatingMergeTree PARTITION BY toYYYYMM(day) ORDER BY (day, key) AS SELECT toDate(ts) AS day, key, sumState(v) AS s FROM events GROUP BY day, key;
CREATE MATERIALIZED VIEW mv_cols TO dst (day Date, c UInt64) AS SELECT toDate(ts) AS day, count() AS c FROM src GROUP BY day;
CREATE MATERIALIZED VIEW mv_cluster ON CLUSTER my_cluster TO dst AS SELECT * FROM src;
CREATE MATERIALIZED VIEW kafka_mv TO events AS SELECT JSONExtractString(raw, 'id') AS id, now() AS ts FROM kafka_queue;
CREATE VIEW v_active_users AS SELECT id, email FROM users WHERE is_active = 1;
CREATE OR REPLACE VIEW v_recent AS SELECT * FROM events WHERE ts > now() - INTERVAL 1 DAY;
CREATE VIEW IF NOT EXISTS v_param AS SELECT * FROM events WHERE user_id = {uid:UInt64};
CREATE TABLE kafka_queue (raw String) ENGINE = Kafka SETTINGS kafka_broker_list = 'kafka:9092', kafka_topic_list = 'events', kafka_group_name = 'ch', kafka_format = 'JSONAsString', kafka_num_consumers = 1;
CREATE TABLE s3_tbl (a UInt32, b String) ENGINE = S3('https://bucket.s3.amazonaws.com/data.csv', 'CSV');
CREATE TABLE pg_tbl (id Int32, name String) ENGINE = PostgreSQL('pg:5432', 'db', 'tbl', 'user', 'pass');
CREATE TABLE mysql_tbl (id Int32) ENGINE = MySQL('mysql:3306', 'db', 'tbl', 'user', 'pass');
CREATE TABLE join_tbl (k UInt64, v String) ENGINE = Join(ANY, LEFT, k);
CREATE TABLE buf (a UInt8) ENGINE = Buffer(default, target, 16, 10, 100, 10000, 1000000, 10000000, 100000000);
CREATE TABLE merge_all (a UInt8) ENGINE = Merge(currentDatabase(), '^events_');
CREATE DICTIONARY country_dict (id UInt64, name String) PRIMARY KEY id SOURCE(CLICKHOUSE(TABLE 'countries')) LIFETIME(MIN 300 MAX 360) LAYOUT(HASHED());
CREATE DICTIONARY ip_trie (prefix String, asn UInt32) PRIMARY KEY prefix SOURCE(FILE(PATH '/data/ip.csv' FORMAT CSV)) LIFETIME(0) LAYOUT(IP_TRIE());
SELECT dictGet('country_dict', 'name', toUInt64(country_id)) AS country FROM events;
SELECT dictGetOrDefault('country_dict', 'name', toUInt64(id), 'n/a') FROM events;
SELECT dictHas('country_dict', toUInt64(5));
SYSTEM RELOAD DICTIONARY country_dict;
CREATE FUNCTION linear_equation AS (x, k, b) -> k * x + b;
CREATE FUNCTION IF NOT EXISTS plus_one AS x -> x + 1;
DROP FUNCTION linear_equation;
DROP VIEW IF EXISTS mv_daily;
DROP DICTIONARY IF EXISTS country_dict;
CREATE ROW POLICY pol ON events USING user_id = 1 TO ALL;
CREATE USER IF NOT EXISTS analyst IDENTIFIED WITH sha256_password BY 'secret';
CREATE ROLE reader;
GRANT SELECT ON default.* TO reader;
GRANT reader TO analyst;
REVOKE SELECT ON default.events FROM analyst;
CREATE QUOTA q FOR INTERVAL 1 HOUR MAX queries = 100 TO analyst;
CREATE SETTINGS PROFILE p SETTINGS max_threads = 4 TO analyst;
